template<class T>
void splitstr(const string &s, vector<T> &out)
{
    istringstream in(s);
    out.clear();
    copy(istream_iterator<T>(in), istream_iterator<T>(), back_inserter(out));
}

static void setup_io(int argc, const char **argv)
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (argc > 1)
    {
        static std::filebuf f;
        f.open(argv[1], std::ios::in);
        cin.rdbuf(&f);
        if (!cin)
        {
            cerr << "Error opening input file\n";
            exit(1);
        }
    }
    if (argc > 2)
    {
        static std::filebuf f;
        f.open(argv[2], std::ios::out | std::ios::trunc);
        cout.rdbuf(&f);
        if (!cout)
        {
            cerr << "Error opening output file\n";
        }
    }
    cin.exceptions(ios::failbit);
}

static ll choose[501][501];

int main(int argc, const char **argv)
{
    setup_io(argc, argv);
    int N, M, P;
    cin >> N >> M >> P;
    for (int i = 0; i <= N; ++i)
    {
        choose[i][0] = choose[i][i] = 1;
        for (int j = 1; j < i; ++j)
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % P;
    }

    vector<ll> dp1(N + 1, 0);
    vector<ll> dpw(N + 1, 1);
    for (int m = 1; m <= M; ++m)
    {
        for (int i = 0; i < m; ++i)
        {
            ll w = (dpw[i] * dpw[m - 1 - i]) % P;
            w = (w * choose[m - 1][i]) % P;
            (dpw[m] += w * (m + 1) % P) %= P;

            ll s1 = (dp1[i] * dpw[m - 1 - i]) % P;
            ll s2 = (dp1[m - 1 - i] * dpw[i]) % P;
            ll add = ((s1 + s2) % P) * (m + 1) % P * choose[m - 1][i] % P;
            add = (add + w * (((ll)i * (i + 1) + (ll)(m - 1 - i) * (m - i)) / 2) % P) % P;
            (dp1[m] += add) %= P;
        }
    }

    vector<vector<ll>> dp(N + 1, vector<ll>(N + 1, 0));
    vector<vector<ll>> dps(N + 1, vector<ll>(N + 1, 0));
    dps[0][0] = 1;
    for (int i = 1; i <= N; ++i)
    {
        dp[i][i] = dp1[i];
        dps[i][i] = dpw[i];
        dps[i][0] = 1;
        for (int j = 1; j < i; ++j)
        {
            dp[i][j] = dp[i - 1][j];
            dps[i][j] = dps[i - 1][j];
            for (int k = 1; k <= j; ++k)
            {
                dps[i][j] = (dps[i][j] + dpw[k] * dps[i - k - 1][j - k] % P * choose[j][k]) % P;
                ll add = (dp[i - k - 1][j - k] * dpw[k] % P + dps[i - k - 1][j - k] * dp1[k]) % P;
                (dp[i][j] += add * choose[j][k]) %= P;
            }
        }
    }
    cout << dp[N][M] << '\n';

    return 0;
}
